// mountain massif as an eroded heightfield: unit radius, unit height, foot at -.55
const ridgeF = (x, z, sd, oct, gain = .5) => { let a = 1, f = 1, r = 0, n = 0, w = 1; let X = x, Z = z; for (let i = 0; i < oct; i++) { let v = 1 - Math.abs(2 * vnoise(X * f, sd * 1.7 + i * 3.1, Z * f, sd + i * 5) - 1); v = v * v * w; w = clamp(v * 1.8); r += a * v; n += a; a *= gain; f *= 2.05; const c = .8, s = .6, tx = X * c - Z * s; Z = X * s + Z * c; X = tx; } return r / n; };
